// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class LmdbNativeGeneratedSourceOptimizerTest {

	@Test
	void installsDomainAndFusesSipIntoMatchingAdjacencyExpansion() {
		String source = "class K { void run() {\n"
				+ "long[] childDomain = materializeNativeDomain(x);\n"
				+ "for (int i=0;i<n;i++) {\n"
				+ "long child = cursor.neighborAtInt(i);\n"
				+ "consume(child);\n"
				+ "}\n"
				+ "} }";
		String optimized = LmdbNativeGeneratedSourceOptimizer.optimize(source);
		assertTrue(optimized.contains("installExactDomain"));
		assertTrue(optimized.contains("sipMayContain"));
		assertEquals(optimized, LmdbNativeGeneratedSourceOptimizer.optimize(optimized));
	}

	@Test
	void doesNotAddSipGuardWithoutAProvenMatchingDomain() {
		String source = "class K { void run() { for(int i=0;i<n;i++){ long child=cursor.neighborAtInt(i); consume(child); } } }";
		String optimized = LmdbNativeGeneratedSourceOptimizer.optimize(source);
		assertTrue(!optimized.contains("sipMayContain"));
	}
}
